using System; using UnityEngine; using UnityEngine.UI;
namespace ThinkingSpace.UI.DesignKit { public sealed class QuestUISegmentedControl:MonoBehaviour { [SerializeField] private Button[] segments=Array.Empty<Button>(); [SerializeField] private int selectedIndex; public int SelectedIndex=>selectedIndex; public void Configure(Button[] values){segments=values??Array.Empty<Button>();SetSelected(0);} public void SetSelected(int index){if(segments.Length==0){selectedIndex=-1;return;}selectedIndex=Mathf.Clamp(index,0,segments.Length-1);for(int i=0;i<segments.Length;i++){ThinkingSpaceButtonStyle style=segments[i]!=null?segments[i].GetComponent<ThinkingSpaceButtonStyle>():null;if(style!=null)style.SetSelected(i==selectedIndex);}} } }
